/* بيانات باب maadin: تُحمَّل عند أول فتح للقسم */
window.MAADIN = {"ch":[{"id":"hadid","t":"الحديد","d":"للحديد في القرآن سورة تحمل اسمه، وقد ورد في سياق المنّة والقوة وأداةً للعمل، ومثلاً للشدة، وفي وصف العذاب؛ وفيه موضع جاء فيه لفظ «حديد» وصفاً للبصر لا معدناً، نُبّه عليه."},{"id":"sanaat","t":"الصناعة بالمعادن وصهرها","d":"آيات في صناعة الدروع وإقامة السدّ وصهر المعادن بالنار، مع ما نقله المفسرون في كيفية ذلك."},{"id":"nuhas","t":"النحاس والقطر والمهل","d":"القطر النحاس المذاب في تفسير المفسرين، وجاء النحاس في وصف العذاب، ومعه لفظ «المهل» الذي نقل القرطبي في معناه أقوالاً منها ما أُذيب من جواهر الأرض."},{"id":"dhahab","t":"الذهب والفضة: زينةً ونقداً وكنزاً","d":"الذهب والفضة في القرآن زينة الدنيا وحُلي أهل الجنة ونقد الناس، وفي الآيات تحذير من كنزهما دون إنفاق الحق."},{"id":"jawahir","t":"اللؤلؤ والمرجان والياقوت","d":"جواهر نفيسة تُذكر في وصف النعمة والجمال، وبعضها من البحر كما ذكر المفسرون؛ فجاءت هنا لقربها من الذهب والفضة في وصف الزينة لا لأنها معادن بالمعنى الجيولوجي."},{"id":"ard","t":"الأرض وما أُخرج منها","d":"آيات فيما أودعه الله في الأرض وما يُخرجه منها، وما يتصل به من الإنفاق والزكاة والركاز في كلام القرطبي والسنة."}],"i":[{"id":"hadid25","ch":"hadid","m":"fe","t":"إنزال الحديد: بأسٌ شديد ومنافع للناس","r":[57,25],"n":"بعد ذكر الكتاب والميزان قال الله: «وأنزلنا الحديد فيه بأس شديد ومنافع للناس وليعلم الله من ينصره»، فجمع بين قوة الحديد ونفعه وبين نصرة الدين.","q":[{"w":"السعدي","bk":"saadi","s":57,"ay":25,"x":"{إنَّ الله لَقَوِيٌّ عزيزٌ}؛ أي: لا يعجِزُه شيءٌ ولا يفوته هاربٌ، ومن قوَّته وعزَّته أن أنزل الحديدَ الذي منه الآلاتُ القويَّة، ومن قوَّته وعزَّته أنه قادرٌ على الانتصار من أعدائه، ولكنَّه يبتلي أولياءه بأعدائه؛ ليعلم من ينصرُهُ بالغيب. وقَرَنَ تعالى بهذا الموضع بين الكتاب والحديد؛ لأنَّ بهذين الأمرين ينصر الله دينه ويُعلي كلمته: بالكتاب الذي فيه الحجَّة والبرهان، والسيف الناصر بإذن الله، وكلاهما قيامُهُ بالعدل والقِسْط، الذي يستدلُّ به على حكمةِ الباري وكماله وكمال شريعتِهِ التي شرعها على ألسنة رسله.","en":"Al-Sa'di: \"Allah is Strong, Almighty\": nothing overpowers Him and no fugitive escapes Him; and part of His strength is that He sent down iron, from which strong instruments come, and He is able to defeat His enemies, yet He tests His friends by means of their enemies to know who helps Him unseen. He joined the Book and iron in this place because by these two Allah supports His religion and raises His word: by the Book, which holds the proof, and by the sword that supports it with Allah's leave, both of them standing on justice and fairness."},{"w":"القرطبي","bk":"qurtubi","s":57,"ay":25,"x":"وَقِيلَ: (أَنْزَلْنَا الْحَدِيدَ) أَيْ أَنْشَأْنَاهُ وَخَلَقْنَاهُ، كَقَوْلِهِ تَعَالَى: (وَأَنْزَلَ لَكُمْ مِنَ الْأَنْعامِ ثَمانِيَةَ أَزْواجٍ) وَهَذَا قَوْلُ الْحَسَنِ. فَيَكُونُ مِنَ الْأَرْضِ غَيْرُ مُنَزَّلٍ مِنَ السَّمَاءِ. وَقَالَ أَهْلُ الْمَعَانِي: أَيْ أَخْرَجَ الْحَدِيدَ مِنَ الْمَعَادِنِ وَعَلَّمَهُمْ صَنْعَتَهُ بِوَحْيِهِ.","en":"Al-Qurtubi: It was also said that \"We sent down iron\" means We brought it into being and created it, like the saying of Allah \"and He sent down for you eight pairs of livestock\"; this is the saying of al-Hasan, so it would be from the earth, not sent down from the sky. And the people of meanings said: He brought iron out of the mines and taught them its craft by His revelation."},{"w":"ابن كثير","bk":"ibnkathir","s":57,"ay":25,"x":"* * وَقَوْلُهُ: ﴿وَأَنزلْنَا الْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ﴾ أَيْ: وَجَعَلْنَا الْحَدِيدَ رَادِعًا لِمَنْ أَبَى الْحَقَّ وَعَانَدَهُ بَعْدَ قِيَامِ الْحُجَّةِ عَلَيْهِ؛ وَلِهَذَا أَقَامَ رَسُولُ اللَّهِ ﷺ بِمَكَّةَ بَعْدَ النُّبُوَّةِ ثَلَاثَ عَشْرَةَ سَنَةً تُوحَى إِلَيْهِ السُّوَرُ الْمَكِّيَّةُ، وَكُلُّهَا جِدَالٌ مَعَ الْمُشْرِكِينَ، وَبَيَانٌ وَإِيضَاحٌ لِلتَّوْحِيدِ، وَتِبْيَانٌ وَدَلَائِلُ، فَلَمَّا قَامَتِ الْحُجَّةُ عَلَى مَنْ خَالَفَ شَرَعَ اللَّهُ الْهِجْرَةَ، وَأَمَرَهُمْ بِالْقِتَالِ بِالسُّيُوفِ، وَضَرْبِ الرِّقَابِ وَالْهَامِ لِمَنْ خَالَفَ الْقُرْآنَ وَكَذَّبَ بِهِ وَعَانَدَهُ.","en":"Ibn Kathir: \"And We sent down iron, in which is great might\": We made iron a deterrent for whoever refuses the truth and is obstinate after the proof has been established against him; for this reason the Messenger of Allah, peace be upon him, stayed in Makkah thirteen years after prophethood while the Makkan surahs were revealed to him, all of them argument with the polytheists and clarification of tawhid with proofs; and when the proof had been established against whoever opposed Allah's law, He legislated the migration and commanded them to fight with swords."}],"h":[{"b":"صحيح البخاري","bk":"bukhari","n":"5029","x":"أَعْطِهَا وَلَوْ خَاتَمًا مِنْ حَدِيدٍ","en":"The Prophet, peace be upon him, said: \"Give her something, even an iron ring.\""}]},{"id":"hajj21","ch":"hadid","m":"fe","t":"مقامع من حديد","r":[22,21],"n":"ذكرت الآية الحديد في وصف عذاب الكافرين: «ولهم مقامع من حديد».","q":[{"w":"السعدي","bk":"saadi","s":22,"ay":21,"x":"{ولهم مقامعُ من حديدٍ}: بيد الملائكة الغلاظ الشداد تضرِبُهم فيها وتقمعُهم.","en":"Al-Sa'di: \"And for them are maces of iron\": in the hands of the stern, mighty angels, who strike them with them and subdue them."}],"h":[]},{"id":"isra50","ch":"hadid","m":"fe","t":"كونوا حجارة أو حديداً","r":[17,50,51],"n":"أمر الله نبيه أن يقول للمنكرين للبعث: كونوا حجارة أو حديداً أو خلقاً مما يكبر في صدوركم، فضرب الحديد مثلاً لأشد ما يتصورونه، وأخبر أن الله يعيدهم كما بدأهم.","q":[{"w":"السعدي","bk":"saadi","s":17,"ay":50,"x":"ولهذا أمر رسوله - صلى الله عليه وسلم - أن يقول لهؤلاء المنكرين للبعث استبعاداً:{قُلۡ كونوا حجارة أو حديداً. أو خلقاً مما يكبر}؛ أي: يعظُم {في صدورِكم}: لتسلموا بذلك ـ على زعمكم ـ من أن تنالكم قدرة الله أو تنفذَ فيكم مشيئتُه؛ فإنكم غير معجزين الله في أيِّ حالة تكونون وعلى أيِّ وصفٍ تتحوَّلون، وليس لكم في أنفسكم تدبيرٌ في حالة الحياة وبعد الممات؛ فدعوا التدبير والتصريف لِمَنْ هو على كلِّ شيء قدير وبكلِّ شيء محيط.","en":"Al-Sa'di: Hence He commanded His Messenger to say to those who deny resurrection out of disbelief: \"Be stones or iron or some creation that is great in your breasts\" so that you may, as you claim, be safe from Allah's power reaching you or His will taking effect in you; you cannot defeat Allah in whatever state you are or whatever form you change into, and you have no control over yourselves in life or after death; so leave management and control to the One who is over all things Competent and encompasses all things."}],"h":[]},{"id":"qaf22","ch":"hadid","m":"fe","t":"فبصرك اليوم حديد (وصف للبصر لا ذكر للمعدن)","r":[50,22],"n":"وردت لفظة «حديد» في قوله: «فبصرك اليوم حديد» وصفاً للبصر بمعنى حدّته وقوته، لا ذكراً للمعدن؛ وذُكرت هنا لئلا تُحسب منه.","q":[{"w":"السعدي","bk":"saadi","s":50,"ay":22,"x":"{فـ}: الآن {كَشَفۡنا عنك غِطاءَك}: الذي غطَّى قلبَك فكثر نومُك واستمرَّ إعراضُك، {فبصرُك اليومَ حديدٌ}: ينظر ما يزعجه ويروِّعه من أنواع العذاب والنَّكال، أو هذا خطابٌ من الله للعبد؛ فإنَّه في الدُّنيا في غفلةٍ عما خُلِقَ له، ولكنه يوم القيامة ينتبه ويزول عنه وَسَنُه في وقت لا يمكِنُه أن يتداركَ الفارطَ ولا يستدركَ الفائتَ.","en":"Al-Sa'di: \"So now We have removed from you your cover\" which covered your heart so that your sleep grew long and your turning away continued, \"and your sight today is sharp\": it sees what disturbs and terrifies it of kinds of punishment and torment; or this is addressed by Allah to the servant, who in this world is heedless of what he was created for, but on the Day of Resurrection he wakes up and his drowsiness leaves him at a time when he can no longer make up for what he missed."}],"h":[]},{"id":"saba10","ch":"sanaat","m":"fe","t":"ألنّا له الحديد: داود والدروع السابغات","r":[34,10,11],"n":"امتنّ الله على داود بأن ألان له الحديد، وأمره بعمل سابغات الدروع وتقدير السرد فيها، وأن يعمل صالحاً.","q":[{"w":"السعدي","bk":"saadi","s":34,"ay":10,"x":"ومن فضله عليه أن ألانَ له الحديدَ؛ ليعملَ الدروع السابغاتِ، وعلَّمه تعالى كيفيَّة صنعتِهِ؛ بأن يقدِّرَه في {السردِ}؛ أي: يقدِّره حَلَقاً ويصنعُه كذلك ثم يُدْخِلُ بعضها ببعض، قال تعالى:{وعلَّمۡناه صنعةَ لَبوس لكم لِتُحۡصِنَكُم من بأسِكُم فهل أنتم شاكرونَ}، ولمَّا ذَكَرَ ما امتنَّ به عليه وعلى آله؛ أمره بشكرِهِ وأن يَعْمَلوا صالحاً، ويراقِبوا الله تعالى فيه بإصلاحه وحفظِهِ من المفسداتِ؛ فإنَّه بصيرٌ بأعمالهم، مطَّلع عليها، لا يخفى عليه منها شيءٌ.","en":"Al-Sa'di: Among His favour to him is that He softened iron for him so that he might make full coats of mail, and He taught him how to make them, by measuring it in the \"sard\", meaning to make it into rings and make it so, then to fit some into others; He said: \"and We taught him the craft of armour for you to protect you in your fighting, so will you be grateful?\" And when He mentioned what He had favoured him and his family with, He commanded them to give thanks and to do righteous deeds and to be mindful of Allah in it by keeping it right and guarding it from what spoils; for He is All-Seeing of their deeds, aware of them, nothing of them hidden from Him."},{"w":"ابن كثير","bk":"ibnkathir","s":34,"ay":10,"x":"* * وَقَوْلُهُ: ﴿وَأَلَنَّا لَهُ الْحَدِيدَ﴾ : قَالَ الْحَسَنُ الْبَصْرِيُّ، وَقَتَادَةُ، وَالْأَعْمَشُ وَغَيْرُهُمْ: كَانَ لَا يَحْتَاجُ أَنْ يُدخلَه نَارًا وَلَا يَضْرِبَهُ بِمِطْرَقَةٍ، بَلْ كَانَ يَفْتِلُهُ بِيَدِهِ مِثْلَ الْخُيُوطِ؛ وَلِهَذَا قَالَ: ﴿أَنِ اعْمَلْ سَابِغَاتٍ﴾ وَهِيَ: الدُّرُوعُ.","en":"Ibn Kathir: And His saying \"and We softened iron for him\": al-Hasan al-Basri, Qatadah, al-A'mash and others said: he did not need to put it in fire or to strike it with a hammer; rather he twisted it with his hand like threads. Hence He said \"Make full coats of mail\", which are armours."}],"h":[]},{"id":"anbiya80","ch":"sanaat","m":"fe","t":"صنعة لبوس لتحصنكم من بأسكم","r":[21,80],"n":"علّم الله داود صنعة الدروع وقاية للناس في الحرب، وختم الآية بسؤال الشكر: «فهل أنتم شاكرون».","q":[{"w":"السعدي","bk":"saadi","s":21,"ay":80,"x":"{وعلَّمۡناه صنعةَ لَبوسٍ لكم}؛ أي: علَّم الله داود عليه السلام صنعةَ الدُّروع؛ فهو أول من صَنَعَها وعلمها وسَرَتْ صناعته إلى مَنْ بعده، فألانَ الله له الحديدَ، وعلَّمه كيف يَسْرُدُها، والفائدة فيها كبيرة؛ {لِتُحۡصِنَكُم من بأسِكُم}؛ أي: هي وقاية لكم وحفظٌ عند الحرب واشتداد البأس.","en":"Al-Sa'di: \"And We taught him the craft of armour for you\", meaning Allah taught Dawud, peace be upon him, the craft of coats of mail; he was the first to make them and teach them and his craft spread to those after him; Allah softened iron for him and taught him how to link them, and the benefit in them is great: \"to protect you in your fighting\", meaning they are a shield and a safeguard for you in war and in the intensity of fighting."},{"w":"السعدي","bk":"saadi","s":21,"ay":80,"x":"يُحتمل أنَّ تعليم الله لداود صنعةَ الدُّروع وإلانتها أمرٌ خارق للعادةِ، وأنْ يكون كما قاله المفسِّرون: إنَّ الله ألانَ له الحديدَ، حتَّى كان يعمَلُه كالعجين والطين من دون إذابةٍ له على النار. ويُحتمل أنَّ تعليم الله له على جاري العادة، وأنَّ إلانة الحديد له بما علَّمه الله من الأسباب المعروفةِ الآن لإذابتها، وهذا هو الظاهر؛ لأنَّ الله امتنَّ [بذلك] على العباد وأمرهم بشكرِها، ولولا أنَّ صنعتَه من الأمور التي جعلها الله مقدورةً للعباد؛ لم يمتنَّ عليهم بذلك ويذكُر فائدتها؛ لأنَّ الدُّروع التي صَنَعَ داود عليه السلام متعذِّرٌ أنْ يكونَ المرادُ أعيانَها، وإنَّما المنَّةُ بالجنس.","en":"Al-Sa'di: It is possible that Allah's teaching Dawud the craft of armour and the softening of it was a miracle beyond custom, and that it was as the exegetes said: Allah softened iron for him until he worked it like dough and clay without melting it in fire. And it is possible that His teaching him was according to the usual way and that the softening of iron for him was through the causes Allah taught him, which are known today for melting it, and this is the apparent meaning, because Allah gave this as a favour to people and commanded them to give thanks for it; and were his craft not among the things Allah made within the capacity of people, He would not have favoured them with it and mentioned its benefit; for the coats of mail Dawud made cannot be meant in their very selves, and the favour is in the kind."}],"h":[]},{"id":"kahf96","ch":"sanaat","m":"fe cu","t":"زبر الحديد والقطر: سد ذي القرنين","r":[18,96,97],"n":"طلب ذو القرنين زبر الحديد حتى ساوى بين الصدفين، وأمر بالنفخ عليها حتى جعلها ناراً، ثم أفرغ عليها قِطراً فاستحكم السد.","q":[{"w":"السعدي","bk":"saadi","s":18,"ay":96,"x":"{آتوني زُبَرَ الحديدِ}؛ أي: قطع الحديد، فأعْطَوْه ذلك، {حتى إذا ساوى بين الصَّدَفين}؛ أي: الجبلين اللذين بُني بينهما السدُّ، {قال انفُخوا}: النار؛ أي أوقدوها إيقاداً عظيماً واستعملوا لها المنافيخ لتشتدَّ فتذيبَ النحاس، فلما ذاب النحاس الذي يريُد أن يُلْصِقَهُ بين زُبَرِ الحديد، {قال آتوني أفۡرِغۡ عليه قِطۡراً}؛ أي: نحاساً مذاباً، فأفرغ عليه القطر، فاستحكم السدُّ استحكاماً هائلاً، وامتنع به من وراءه من الناس من ضرر يأجوج ومأجوج.","en":"Al-Sa'di: \"Bring me sheets of iron\", meaning pieces of iron, and they gave him that; \"until, when he had levelled between the two mountain-sides\" which the barrier was built between, \"he said: Blow\", meaning kindle the fire greatly and use bellows for it so that it intensifies and melts the copper; and when the copper he wanted to join between the sheets of iron melted, \"he said: Bring me that I may pour over it molten brass\", meaning molten copper; and he poured the molten brass over it, so the barrier became tremendously firm, and the people behind it were protected by it from the harm of Yajuj and Majuj."},{"w":"القرطبي","bk":"qurtubi","s":18,"ay":96,"x":"وَالْقَطْرُ عِنْدَ أَكْثَرِ الْمُفَسِّرِينَ النُّحَاسُ الْمُذَابُ، وَأَصْلُهُ مِنَ الْقَطْرِ، لِأَنَّهُ إِذَا أُذِيبَ قَطَرَ كَمَا يَقْطُرُ الْمَاءُ. وَقَالَتْ فِرْقَةٌ: الْقِطْرُ الْحَدِيدُ الْمُذَابُ.","en":"Al-Qurtubi: Al-qitr, according to most exegetes, is molten copper; its origin is from \"qatr\" (dripping), because when melted it drips as water drips. And a group said: al-qitr is molten iron."}],"h":[]},{"id":"rad17","ch":"sanaat","m":"au ag cu fe","t":"ومما يوقدون عليه في النار: مثل الحق والباطل","r":[13,17],"n":"ضرب الله مثلاً بما يُوقد عليه في النار ابتغاء حلية أو متاع فيعلوه زبد مثل زبد الماء، وهو مثل للحق الباقي والباطل الزائل.","q":[{"w":"ابن كثير","bk":"ibnkathir","s":13,"ay":17,"x":"وَقَالَ الْعَوْفِيُّ عَنِ ابْنِ عَبَّاسٍ قَوْلُهُ: ﴿أَنزلَ مِنَ السَّمَاءِ مَاءً فَسَالَتْ أَوْدِيَةٌ بِقَدَرِهَا فَاحْتَمَلَ السَّيْلُ زَبَدًا رَابِيًا﴾ يَقُولُ: احْتَمَلَ السَّيْلُ مَا فِي الْوَادِي مِنْ عُودٍ ودِمْنَة ﴿وَمِمَّا يُوقِدُونَ عَلَيْهِ فِي النَّارِ﴾ فَهُوَ الذَّهَبُ وَالْفِضَّةُ وَالْحِلْيَةُ وَالْمَتَاعُ وَالنُّحَاسُ وَالْحَدِيدُ، فَلِلنُّحَاسِ وَالْحَدِيدِ خَبَثٌ، فَجَعَلَ اللَّهُ مَثَلَ خَبَثِهِ كَزَبَدِ الْمَاءِ، فَأَمَّا مَا يَنْفَعُ النَّاسَ فَالذَّهَبُ وَالْفِضَّةُ، وَأَمَّا مَا يَنْفَعُ الْأَرْضَ فَمَا شَرِبَتْ مِنَ الْمَاءِ فَأَنْبَتَتْ.","en":"Ibn Kathir: Al-'Awfi reported from Ibn 'Abbas on His saying \"He sent down water from the sky and valleys flowed according to their measure, and the torrent carried a swelling foam\": the torrent carried what was in the valley of wood and refuse; \"and from what they heat in the fire\" it is gold, silver, ornaments, goods, copper and iron; copper and iron have dross, so Allah made the parable of its dross like the foam of water; as for what benefits people, it is gold and silver, and what benefits the earth is what it drank of the water and so brought forth growth."},{"w":"القرطبي","bk":"qurtubi","s":13,"ay":17,"x":"(ابْتِغاءَ حِلْيَةٍ) أَيْ حِلْيَةِ الذَّهَبِ وَالْفِضَّةِ. (أَوْ مَتاعٍ زَبَدٌ مِثْلُهُ) قَالَ مُجَاهِدٌ: الْحَدِيدُ وَالنُّحَاسُ وَالرَّصَاصُ.","en":"Al-Qurtubi: \"Seeking ornaments\", meaning ornaments of gold and silver; \"or goods, a foam like it\": Mujahid said: iron, copper and lead."}],"h":[]},{"id":"saba12","ch":"nuhas","m":"cu","t":"وأسلنا له عين القطر","r":[34,12],"n":"أنعم الله على سليمان بأن أسال له عين القطر، وفسّرها السعدي بعين النحاس وتسهيل الأسباب في استخراج ما يُستخرج منها.","q":[{"w":"السعدي","bk":"saadi","s":34,"ay":12,"x":"لمَّا ذَكَرَ فضلَه على داود عليه السلام؛ ذكر فضلَه على ابنه سليمان عليه الصلاة والسلام، وأنَّ الله سخَّر له الريح تجري بأمرِهِ وتحمِلُه وتحمِلُ جميعَ ما معه وتقطعُ المسافة البعيدةَ جدًّا في مدةٍ يسيرةٍ، فتسير في اليوم مسيرة شهرين:{غدوُّها شهرٌ}؛ أي: أول النهار إلى الزوال، {ورواحُها شهرٌ}: من الزَّوال إلى آخر النهار، {وأسَلۡنا له عَيۡنَ القِطۡرِ}؛ أي: سخَّرْنا له عينَ النُّحاس وسهَّلْنا له الأسباب في استخراج ما يُستخرج منها من الأواني وغيرها، وسخَّرَ اللهُ له أيضاً الشياطين والجنَّ لا يقدِرون أن يستعصوا عن أمرِهِ، {ومن يَزِغۡ منهم عن أمرِنا نُذِقۡه من عذاب السعير} …","en":"Al-Sa'di: When He mentioned His favour to Dawud, peace be upon him, He mentioned His favour to his son Sulayman, peace be upon him: that Allah subjected the wind for him running at his command, carrying him and everything with him and covering a very long distance in a short time, travelling in a day the distance of two months: \"its morning course a month\", meaning from the start of the day till noon, \"and its evening course a month\", from noon till the end of the day; \"and We made a spring of molten brass flow for him\", meaning We made the spring of copper subject to him and made easy for him the means of extracting from it what is extracted of vessels and other things; and Allah also subjected to him the devils and the jinn, who could not disobey his command: \"and whoever of them deviates from Our command, We make him taste of the punishment of the Blaze\"."}],"h":[]},{"id":"rahman35","ch":"nuhas","m":"cu","t":"شواظ من نار ونحاس","r":[55,35,36],"n":"ذُكر النحاس في وصف ما يُرسل على المكذّبين: «يرسل عليكما شواظ من نار ونحاس فلا تنتصران».","q":[{"w":"السعدي","bk":"saadi","s":55,"ay":35,"x":"أي: {يرسَل عليكما} لهبٌ صافٍ من النار {ونحاسٌ} وهو اللهب الذي قد خالَطَه الدخانُ. والمعنى: أنَّ هذين الأمرين الفظيعين يرسلانِ عليكما [يا معشر الجن والإنس] ويحيطانِ بكما فلا تنتصران؛ لا بناصرٍ من أنفسكم، ولا بأحدٍ ينصُرُكم من دون الله.","en":"Al-Sa'di: \"There will be sent upon you\" a pure flame of fire \"and copper\", which is the flame that smoke has mixed with. The meaning: these two dreadful things are sent upon you, O company of jinn and men, and surround you, so you will not defend yourselves, neither by help from yourselves nor by anyone who helps you apart from Allah."}],"h":[]},{"id":"kahf29","ch":"nuhas","m":"cu fe","t":"ماء كالمهل يشوي الوجوه","r":[18,29],"n":"وصف الله شراب أهل النار بأنه «كالمهل يشوي الوجوه»؛ وفي معنى المهل أقوال للمفسرين نقلها القرطبي.","q":[{"w":"السعدي","bk":"saadi","s":18,"ay":29,"x":"{وإن يَسۡتغيثوا}؛ أي: يطلبوا الشراب ليطفئ ما نزل بهم من العطش الشديد؛ {يُغاثوا بماءٍ كالمهل}؛ أي: كالرصاص المذاب أو كعكر الزيت من شدَّة حرارته.","en":"Al-Sa'di: \"And if they call for relief\", meaning ask for a drink to quench the severe thirst that befell them, \"they will be relieved with water like muhl\", meaning like molten lead or like the dregs of oil because of its intense heat."},{"w":"القرطبي","bk":"qurtubi","s":18,"ay":29,"x":"وَقَالَ أَبُو عُبَيْدَةَ: هُوَ كُلُّ مَا أُذِيبَ مِنْ جَوَاهِرِ الْأَرْضِ مِنْ حَدِيدٍ وَرَصَاصٍ ونحاس وقصدير، فَتَمُوجُ بِالْغَلَيَانِ، فَذَلِكَ الْمُهْلُ.","en":"Al-Qurtubi: Abu 'Ubaydah said: it is everything melted of the earth's substances, of iron, lead, copper and tin, so it surges with boiling; that is the muhl."},{"w":"القرطبي","bk":"qurtubi","s":18,"ay":29,"x":"فِي الصِّحَاحِ\" الْمُهْلُ\" النحاس المذاب. ابن الاعرابي: المهل لمذاب من الرَّصَاصِ. وَقَالَ أَبُو عَمْرٍو. الْمُهْلُ دُرْدِيُّ الزَّيْتِ. وَالْمُهْلُ أَيْضًا الْقَيْحُ وَالصَّدِيدُ.","en":"Al-Qurtubi: In al-Sihah: \"al-muhl\" is molten copper. Ibn al-A'rabi: al-muhl is what is melted of lead. And Abu 'Amr said: al-muhl is the dregs of oil. And al-muhl is also pus and discharge."}],"h":[]},{"id":"dukhan45","ch":"nuhas","m":"cu","t":"طعام الأثيم كالمهل","r":[44,43,46],"n":"شُبّه طعام الأثيم بالمهل يغلي في البطون كغلي الحميم، وفسّره السعدي هنا بالصديد المنتن شديد الحرارة.","q":[{"w":"السعدي","bk":"saadi","s":44,"ay":45,"x":"لما ذَكَرَ يوم القيامة، وأنه يفصِلُ بين عباده فيه؛ ذَكَرَ افتراقهم إلى فريقين: فريقٍ في الجنة، وفريقٍ في السعير، وهم الآثمون بعمل الكفر والمعاصي، وأنَّ طعامهم {شجرة الزَّقُّوم}: شرُّ الأشجار وأفظعُها، وأنَّ طعامها {كالمهل}؛ أي: كالصديد المنتن خبيث الريح والطعم شديد الحرارة، {يَغۡلي في} بطونهم {كغَلۡي الحميم} …","en":"Al-Sa'di: When He mentioned the Day of Resurrection and that He judges between His servants on it, He mentioned their division into two groups: a group in Paradise and a group in the Blaze, who are the sinners by acts of disbelief and disobedience; and that their food is \"the tree of Zaqqum\", the worst and most hideous of trees, and that its food is \"like muhl\", meaning like foul pus, evil in smell and taste, intensely hot, \"boiling in\" their bellies \"like the boiling of scalding water\"."}],"h":[]},{"id":"maarij8","ch":"nuhas","m":"cu fe","t":"يوم تكون السماء كالمهل","r":[70,8,9],"n":"شُبّهت السماء يوم القيامة بالمهل والجبال بالعهن المنفوش؛ وفسّر السعدي المهل هنا بالرصاص المذاب.","q":[{"w":"السعدي","bk":"saadi","s":70,"ay":8,"x":"أي: {يوم} القيامة تقع فيه هذه الأمور العظيمة {تكونُ السماءُ كالمُهۡل}: وهو الرصاص المذاب من تشقُّقها وبلوغ الهول منها كلَّ مبلغ، {وتكونُ الجبالُ كالعِهۡن}: وهو الصوف المنفوش، ثم تكون بعد ذلك هباءً منثوراً فتضمحلُّ.","en":"Al-Sa'di: That is, \"on the day\" of Resurrection when these tremendous things occur, \"the sky will be like muhl\", which is molten lead, from its splitting and the terror reaching it to the utmost, \"and the mountains will be like carded wool\", then after that they will become scattered dust and vanish."}],"h":[]},{"id":"ali14","ch":"dhahab","m":"au ag","t":"القناطير المقنطرة من الذهب والفضة","r":[3,14],"n":"جعل الله حب القناطير المقنطرة من الذهب والفضة من الشهوات المزيّنة للناس، وللمفسرين أقوال في مقدار القنطار.","q":[{"w":"ابن كثير","bk":"ibnkathir","s":3,"ay":14,"x":"وَقَدِ اخْتَلَفَ الْمُفَسِّرُونَ فِي مِقْدَارِ الْقِنْطَارِ عَلَى أَقْوَالٍ، وَحَاصِلُهَا: أَنَّهُ الْمَالُ الْجَزِيلُ، كَمَا قَالَهُ الضَّحَّاكُ وَغَيْرُهُ، وَقِيلَ: أَلْفُ دِينَارٍ. وَقِيلَ: أَلْفٌ وَمِائَتَا دِينَارٍ. وَقِيلَ: اثْنَا عَشَرَ أَلْفًا. وَقِيلَ: أَرْبَعُونَ أَلْفًا. وَقِيلَ: سِتُّونَ أَلْفًا وَقِيلَ: سَبْعُونَ أَلْفًا. وَقِيلَ: ثَمَانُونَ أَلْفًا. وَقِيلَ غَيْرُ ذَلِكَ.","en":"Ibn Kathir: The exegetes differed on the measure of the qintar in several sayings, the sum of which is that it is abundant wealth, as al-Dahhak and others said; and it was said: a thousand dinars; and it was said: one thousand two hundred dinars; and it was said: twelve thousand; and it was said: forty thousand; and it was said: sixty thousand; and it was said: seventy thousand; and it was said: eighty thousand; and it was said other than that."},{"w":"القرطبي","bk":"qurtubi","s":3,"ay":14,"x":"قَالَ الْعُلَمَاءُ: ذَكَرَ اللَّهُ تَعَالَى أَرْبَعَةَ أَصْنَافٍ مِنَ الْمَالِ، كُلُّ نَوْعٍ مِنَ الْمَالِ يَتَمَوَّلُ بِهِ صِنْفٌ مِنَ النَّاسِ، أَمَّا الذَّهَبُ وَالْفِضَّةُ فَيَتَمَوَّلُ بِهَا التُّجَّارُ، وَأَمَّا الْخَيْلُ الْمُسَوَّمَةُ فَيَتَمَوَّلُ بِهَا الْمُلُوكُ، وَأَمَّا الْأَنْعَامُ فَيَتَمَوَّلُ بِهَا أَهْلُ الْبَوَادِي، وَأَمَّا الْحَرْثُ فَيَتَمَوَّلُ بِهَا أَهْلُ الرَّسَاتِيقِ .","en":"Al-Qurtubi: The scholars said: Allah mentioned four kinds of wealth, each kind being held as property by a class of people: gold and silver are held by merchants, the marked horses by kings, livestock by people of the desert, and tilled land by people of the farmland."}],"h":[{"b":"صحيح مسلم","bk":"muslim","n":"1584","x":"الذَّهَبُ بِالذَّهَبِ وَالْفِضَّةُ بِالْفِضَّةِ وَالْبُرُّ بِالْبُرِّ وَالشَّعِيرُ بِالشَّعِيرِ وَالتَّمْرُ بِالتَّمْرِ وَالْمِلْحُ بِالْمِلْحِ مِثْلاً بِمِثْلٍ يَدًا بِيَدٍ فَمَنْ زَادَ أَوِ اسْتَزَادَ فَقَدْ أَرْبَى الآخِذُ وَالْمُعْطِي فِيهِ سَوَاءٌ","en":"The Prophet, peace be upon him, said: \"Gold for gold, silver for silver, wheat for wheat, barley for barley, dates for dates, salt for salt, like for like, hand to hand; whoever gives more or asks for more has dealt in usury, the taker and the giver alike.\""}]},{"id":"ali75","ch":"dhahab","m":"au","t":"القنطار والدينار في الأمانة","r":[3,75],"n":"ذكرت الآية القنطار والدينار مثلين للكثير والقليل من المال في الأمانة والخيانة بين أهل الكتاب.","q":[{"w":"السعدي","bk":"saadi","s":3,"ay":75,"x":"يخبر تعالى عن أهل الكتاب أن منهم طائفة أمناء بحيث لو أمنته على قناطير من النقود وهي المال الكثير يؤده إليك، ومنهم طائفة خونة يخونك في أقل القليل …","en":"Al-Sa'di: Allah informs about the People of the Book that among them is a group who are trustworthy, so that if you entrusted them with qintars of money, meaning much wealth, they would return it to you, and among them is a group of traitors who betray you in the least of little things …"}],"h":[]},{"id":"ali91","ch":"dhahab","m":"au","t":"ملء الأرض ذهباً","r":[3,91],"n":"أخبر الله أن الكافر لو افتدى بملء الأرض ذهباً ما قُبل منه، فجعل الذهب مثلاً لأعظم ما يُبذل.","q":[{"w":"السعدي","bk":"saadi","s":3,"ay":91,"x":"ثم إنه تعالى استثنى من هذا الوعيد التائبين من كفرهم وذنوبهم المصلحين لعيوبهم فإن الله يغفر لهم ما قدموه ويعفو عنهم ما أسلفوه، ولكن من كفر وأصر على كفره، ولم يزدد إلا كفراً حتى مات على كفره، فهؤلاء هم الضالون عن طريق الهدى السالكون لطريق الشقاء، وقد استحقوا بهذا العذاب الأليم، فليس لهم ناصر من عذاب الله ولو بذلوا ملء الأرض ذهباً ليفتدوا به لم ينفعهم شيئاً.","en":"Al-Sa'di: Then He excepted from this threat those who repent of their disbelief and sins, who set right their faults, for Allah forgives them what they put forward and pardons what they sent ahead; but whoever disbelieved and persisted in his disbelief, increasing only in disbelief until he died upon it, those are the ones who strayed from the path of guidance and followed the path of misery, and by this they deserved the painful punishment; they have no helper from Allah's punishment, and even if they gave the earth's fill of gold to ransom themselves, it would not benefit them at all."}],"h":[]},{"id":"tawba34","ch":"dhahab","m":"au ag","t":"الذين يكنزون الذهب والفضة","r":[9,34,35],"n":"توعّد الله الذين يكنزون الذهب والفضة ولا ينفقونها في سبيله بعذاب أليم، يوم يُحمى عليها في نار جهنم فتُكوى بها جباههم وجنوبهم وظهورهم.","q":[{"w":"ابن كثير","bk":"ibnkathir","s":9,"ay":34,"x":"وَأَمَّا الْكَنْزُ فَقَالَ مَالِكٌ، عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ، عَنِ ابْنِ عُمَرَ أَنَّهُ قَالَ: هُوَ الْمَالُ الَّذِي لَا تُؤَدَّى مِنْهُ الزَّكَاةُ. وَرَوَى الثَّوْرِيُّ وَغَيْرُهُ عَنْ عُبَيد اللَّهِ عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ قَالَ: مَا أُدِّي زكاتُه فَلَيْسَ بِكَنْزٍ وَإِنْ كَانَ تَحْتَ سَبْعِ أَرَضِينَ، وَمَا كَانَ ظَاهِرًا لَا تُؤَدَّى زَكَاتُهُ فَهُوَ كَنْزٌ وَقَدْ رُوي هذا عن ابن عَبَّاسٍ، وَجَابِرٍ، وَأَبِي هُرَيْرَةَ مَوْقُوفًا وَمَرْفُوعًا وَعُمَرَ بْنِ الْخَطَّابِ، نَحْوَهُ، رَضِيَ اللَّهُ عَنْهُمْ: \"أَيُّمَا مَالٍ أَدَّيْتَ زَكَاتَهُ فَلَيْسَ بِكَنْزٍ وَإِنْ كَانَ مَدْفُونًا فِي الْأَرْضِ، وَأَيُّمَا مَالٍ لَمْ تُؤَدِّ زَكَاتَهُ فَهُوَ كَنْزٌ يُكْوَى بِهِ صَاحِبُهُ وَإِنْ كَانَ عَلَى وَجْهِ الْأَرْضِ\".","en":"Ibn Kathir: As for hoarded wealth, Malik reported from 'Abdullah ibn Dinar from Ibn 'Umar that he said: it is the wealth from which zakat is not paid. And al-Thawri and others reported from 'Ubaydullah from Nafi' from Ibn 'Umar: what has had its zakat paid is not a hoard even if it is under seven earths, and what is visible and has not had its zakat paid is a hoard; this was reported from Ibn 'Abbas, Jabir and Abu Hurayrah, halting at them and attributed to the Prophet, and from 'Umar ibn al-Khattab similarly, may Allah be pleased with them: \"Any wealth whose zakat you paid is not a hoard even if buried in the earth, and any wealth whose zakat you did not pay is a hoard with which its owner will be branded even if it is on the surface of the earth.\""}],"h":[{"b":"صحيح مسلم","bk":"muslim","n":"987","x":"مَا مِنْ صَاحِبِ ذَهَبٍ وَلاَ فِضَّةٍ لاَ يُؤَدِّي مِنْهَا حَقَّهَا إِلاَّ إِذَا كَانَ يَوْمُ الْقِيَامَةِ صُفِّحَتْ لَهُ صَفَائِحَ مِنْ نَارٍ فَأُحْمِيَ عَلَيْهَا فِي نَارِ جَهَنَّمَ فَيُكْوَى بِهَا جَنْبُهُ وَجَبِينُهُ وَظَهْرُهُ كُلَّمَا بَرَدَتْ أُعِيدَتْ لَهُ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ حَتَّى يُقْضَى بَيْنَ الْعِبَادِ فَيُرَى سَبِيلُهُ إِمَّا إِلَى الْجَنَّةِ وَإِمَّا إِلَى النَّارِ","en":"The Prophet, peace be upon him, said: \"No owner of gold or silver who does not pay what is due from it but, on the Day of Resurrection, plates of fire will be beaten out for him and heated in the fire of Hell, and with them his side, his forehead and his back will be branded; whenever they cool they are returned to him, in a day whose measure is fifty thousand years, until judgement is passed between the servants, and he sees his way, either to Paradise or to the Fire.\""}]},{"id":"kahf19","ch":"dhahab","m":"ag","t":"فابعثوا أحدكم بورقكم","r":[18,19],"n":"أرسل أصحاب الكهف أحدهم بورقهم إلى المدينة ليشتري لهم طعاماً؛ وفسّر السعدي الورق بالدراهم.","q":[{"w":"السعدي","bk":"saadi","s":18,"ay":19,"x":"ثم إنَّهم لما تساءلوا بينهم، وجرى منهم ما أخبر الله به؛ أرسلوا أحدَهم بوَرِقِهم؛ أي: بالدراهم التي كانت معهم …","en":"Al-Sa'di: Then, when they had questioned one another and what Allah reported had passed between them, they sent one of them with their \"waraq\", meaning the dirhams they had with them …"}],"h":[]},{"id":"yusuf20","ch":"dhahab","m":"ag","t":"دراهم معدودة: ثمن يوسف","r":[12,20],"n":"ذكرت الآية الدراهم المعدودة ثمناً بخساً ليوسف عليه السلام.","q":[{"w":"السعدي","bk":"saadi","s":12,"ay":20,"x":"وكان إخوته قريباً منه، فاشتراه السيارةُ منهم {بثمنٍ بخسٍ}؛ أي: قليل جدًّا، فسَّره بقوله:{دراهمَ معدودةٍ وكانوا فيه من الزَّاهدينَ} …","en":"Al-Sa'di: His brothers were near him, and the travellers bought him from them \"for a paltry price\", meaning very little, which He explained by His saying \"a few counted dirhams, and they were of those who held him cheap\" …"}],"h":[]},{"id":"kahf31","ch":"dhahab","m":"au","t":"أساور من ذهب في جنات عدن","r":[18,31],"n":"وعد الله الصالحين بجنات عدن تجري من تحتها الأنهار، يُحلَّون فيها من أساور من ذهب ويلبسون ثياباً خضراً من سندس وإستبرق.","q":[{"w":"السعدي","bk":"saadi","s":18,"ay":31,"x":"ودلت الآية الكريمة وما أشبهها على أن الحِلْيَةَ عامَّةٌ للذكور والإناث؛ كما ورد في الأخبار الصحيحة؛ لأنَّه أطلقها في قوله:{يُحَلَّوۡنَ}، وكذلك الحرير ونحوه.","en":"Al-Sa'di: This verse and its like show that ornament is general for males and females, as reported in the sound reports, because He used the general wording \"they will be adorned\", and likewise silk and the like."}],"h":[]},{"id":"fatir33","ch":"dhahab","m":"au gem","t":"أساور من ذهب ولؤلؤ","r":[35,33],"n":"يُحلّى أهل الجنة بأساور من ذهب ولؤلؤ، ولباسهم فيها حرير.","q":[{"w":"السعدي","bk":"saadi","s":35,"ay":33,"x":"والعَدْنُ: الإقامة؛ فجنات عدنٍ؛ أي: جنات إقامة، أضافها للإقامة لأنَّ الإقامةَ والخلودَ وصفُها ووصفُ أهلها، {يُحَلَّوۡنَ فيها من أساورَ من ذهبٍ}: وهو الحُلِيُّ الذي يُجعل في اليدين على ما يحبُّون ويرونَ أنَّه أحسنُ من غيره، الرجال والنساء في الحلية في الجنة سواء. {و} يحلَّوْن فيها {لؤلؤاً}: يُنْظَمُ في ثيابهم وأجسادهم، {ولباسُهُم فيها حريرٌ}: من سندس ومن إستبرقٍ أخضر.","en":"Al-Sa'di: \"Adn\" means residence, so the Gardens of Adn are gardens of residence; He attributed them to residence because residence and eternity are their description and the description of their people; \"they will be adorned therein with bracelets of gold\", which is the ornament put on the arms in the way they love and see to be finer than another; men and women are equal in ornament in Paradise; \"and pearls\" strung into their garments and bodies, \"and their garments therein will be silk\", of fine silk and green brocade."}],"h":[]},{"id":"insan15","ch":"dhahab","m":"ag","t":"آنية من فضة وأكواب قوارير","r":[76,15,16],"n":"يُطاف على أهل الجنة بآنية من فضة وأكواب كانت قوارير، قوارير من فضة قدّروها تقديراً.","q":[{"w":"السعدي","bk":"saadi","s":76,"ay":15,"x":"{ويُطافُ عليهم}؛ أي: يدور الولدان والخدم على أهل الجنة ، {بآنيةٍ من فضَّةٍ وأكوابٍ كانت قواريرَ. قواريرَ من فضَّةٍ}؛ أي: مادتها فضَّةٌ، وهي على صفاء القوارير، وهذا من أعجب الأشياء؛ أن تكون الفضَّةُ الكثيفة من صفاء جوهرها وطيب معدنها على صفاء القوارير، {قدَّروها تَقۡديراً}؛ أي: قدَّروا الأواني المذكورة على قدرِ رِيِّهم؛ لا تزيدُ ولا تنقصُ؛ لأنَّها لو زادت؛ نقصتْ لذَّتها، ولو نقصت؛ لم تكفِهِم لرِيِّهم.","en":"Al-Sa'di: \"And there will be passed around\" among them, meaning the boys and servants circle among the people of Paradise, \"vessels of silver and goblets that were crystal, crystal of silver\", meaning their substance is silver while having the clarity of crystal, and this is among the most wondrous things, that dense silver has, from the clarity of its essence and goodness of its mine, the clarity of crystal; \"they measured them exactly\", meaning they measured the mentioned vessels to the measure of their quenching, neither more nor less, because were it more, its pleasure would lessen, and were it less, it would not suffice their quenching."}],"h":[{"b":"صحيح مسلم","bk":"muslim","n":"2065","x":"الَّذِي يَشْرَبُ فِي آنِيَةِ الْفِضَّةِ إِنَّمَا يُجَرْجِرُ فِي بَطْنِهِ نَارَ جَهَنَّمَ","en":"The Prophet, peace be upon him, said: \"The one who drinks from vessels of silver is only making the fire of Hell gurgle in his belly.\""}]},{"id":"insan21","ch":"dhahab","m":"ag","t":"أساور من فضة","r":[76,21],"n":"وصف الله أهل الجنة بأنهم «حلّوا أساور من فضة وسقاهم ربهم شراباً طهوراً».","q":[{"w":"السعدي","bk":"saadi","s":76,"ay":21,"x":"{عاليهم ثيابُ سندسٍ خضرٌ}؛ أي: قد جلَّلتهم ثياب السندس والإستبرق الأخضران اللَّذان هما أجلُّ أنواع الحرير، فالسُّندس ما غلظ من الحرير، والإستبرقُ ما رقَّ منه، {وحُلُّوا أساوِرَ من فضَّةٍ} …","en":"Al-Sa'di: \"Upon them will be garments of green fine silk\", meaning they are covered with garments of sundus and istabraq, green, which are the finest kinds of silk, sundus being the thicker silk and istabraq the thinner, \"and they will be adorned with bracelets of silver\" …"}],"h":[]},{"id":"zukhruf71","ch":"dhahab","m":"au","t":"صحاف من ذهب وأكواب","r":[43,71],"n":"يُطاف على أهل الجنة بصحاف من ذهب وأكواب، وفيها ما تشتهيه الأنفس وتلذ الأعين وهم فيها خالدون.","q":[{"w":"السعدي","bk":"saadi","s":43,"ay":71,"x":"{يطافُ عليهم بصحافٍ من ذهبٍ وأكوابٍ}؛ أي: تدور عليهم خدَّامهم من الولدانِ المخلَّدين بطعامِهم بأحسنِ الأواني وأفخرِها، وهي صحافُ الذهب، وبشرابهم بألطف الأواني، وهي الأكواب التي لا عرى لها، وهي من أصفى الأواني، من فضة أعظم من صفاءِ القوارير، {وفيها}؛ أي: الجنة {ما تشتهيه الأنفسُ وتلذُّ الأعينُ}: وهذا اللفظ جامعٌ، يأتي على كلِّ نعيم وفرح وقرَّة عين وسرور قلبٍ؛ فكلُّ ما تشتهيه النُّفوس من مطاعم ومشارب وملابس ومناكح، ولذّته العيون من مناظر حسنةٍ وأشجارٍ محدقةٍ ونعم مونقةٍ ومبانٍ مزخرفةٍ؛ فإنَّه حاصلٌ فيها معدٌّ لأهلها على أكمل الوجوه وأفضلها؛ كما قال تعالى:{لهم فيها فاكهةٌ ولهم ما يَدَّعونَ}.","en":"Al-Sa'di: \"Platters of gold and cups will be passed around them\", meaning their servants, the immortal boys, circle among them with their food in the finest and noblest vessels, which are the platters of gold, and with their drink in the gentlest vessels, which are the cups that have no handles, among the clearest of vessels, of silver clearer than crystal, \"and therein is whatever the souls desire and the eyes delight in\": this wording is comprehensive and comes upon every bliss, joy, comfort of the eye and delight of the heart; everything the souls desire of food, drink, clothing and marriage, and the eyes delight in of beautiful sights, encircling trees, lovely blessings and adorned buildings is present there, prepared for its people in the most complete and best way, as He said: \"They will have fruit therein, and they will have whatever they ask for\"."}],"h":[{"b":"صحيح البخاري","bk":"bukhari","n":"5426","x":"لاَ تَلْبَسُوا الْحَرِيرَ وَلاَ الدِّيبَاجَ وَلاَ تَشْرَبُوا فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ، وَلاَ تَأْكُلُوا فِي صِحَافِهَا، فَإِنَّهَا لَهُمْ فِي الدُّنْيَا وَلَنَا فِي الآخِرَةِ","en":"The Prophet, peace be upon him, said: \"Do not wear silk or brocade, and do not drink from vessels of gold and silver, and do not eat from their plates, for they are for them in this world and for us in the Hereafter.\""}]},{"id":"zukhruf33","ch":"dhahab","m":"ag au","t":"سقفاً من فضة ومعارج","r":[43,33,35],"n":"لولا أن يكون الناس أمة واحدة لجعل الله لبيوت الكافرين سقفاً من فضة ومعارج عليها يظهرون، وإنما ذلك متاع الحياة الدنيا.","q":[{"w":"السعدي","bk":"saadi","s":43,"ay":33,"x":"يخبر تعالى بأنَّ الدُّنيا لا تسوى عنده شيئاً، وأنَّه لولا لطفُه ورحمتُه بعباده التي لا يقدم عليها شيئاً؛ لوسَّع الدُّنيا على الذين كفروا توسيعاً عظيماً، ولَجَعَلَ {لبيوتهم سُقُفاً من فضَّة ومعارجَ}؛ أي: درجاً من فضة، {عليها يظهرونَ}: إلى سطوحهم، {ولبيوتِهِم أبواباً وسُرراً عليها يتَّكِئونَ}: من فضَّة، ولجعل لهم {زُخۡرفاً}؛ أي: لزخرف لهم دُنياهم بأنواع الزخارف وأعطاهم ما يشتهون، ولكن منعه من ذلك رحمتُه بعباده؛ خوفاً عليهم من التسارع في الكفر وكثرة المعاصي بسبب حبِّ الدُّنيا. ففي هذا دليلٌ على أنَّه يمنع العبادَ بعضَ أمور الدُّنيا منعاً عامًّا أو خاصًّا لمصالحهم، وأنَّ الدُّنيا لا تزن عند الله جناح بعوضة.","en":"Al-Sa'di: Allah informs that the world is worth nothing with Him, and that were it not for His kindness and mercy to His servants, which nothing precedes, He would have expanded the world greatly for those who disbelieved and would have made \"for their houses roofs of silver and stairways\", meaning steps of silver, \"upon which they climb\" to their rooftops, \"and for their houses doors and couches upon which they recline\", of silver, and would have made for them \"gold adornment\", meaning He would have adorned their world for them with kinds of ornaments and given them what they desire, but His mercy to His servants prevented that, fearing for them hastening into disbelief and many sins because of the love of the world. In this is evidence that He withholds from servants some worldly things, generally or specifically, for their interests, and that the world does not weigh the wing of a gnat with Allah."}],"h":[]},{"id":"zukhruf53","ch":"dhahab","m":"au","t":"أسورة من ذهب: قول فرعون","r":[43,53],"n":"قال فرعون في موسى عليه السلام: «فلولا ألقي عليه أسورة من ذهب»، فجعل الحلية علامة على الرسالة.","q":[{"w":"السعدي","bk":"saadi","s":43,"ay":53,"x":"ثم قال فرعونُ: {فلولا ألۡقِيَ عليه أسورةٌ من ذهبٍ}؛ أي: فهلاَّ كان موسى بهذه الحالة: أن يكون مزيناً مجملاً بالحُلِيِّ والأساور، {أو جاء معه الملائكة مقترنين}: يعاونونه على دعوته ويؤيِّدونه على قوله.","en":"Al-Sa'di: Then Pharaoh said: \"Why then have bracelets of gold not been cast upon him?\", meaning: why was Musa not in this state, adorned and beautified with ornaments and bracelets, \"or angels come with him in company\": helping him in his call and supporting him in his word."}],"h":[]},{"id":"rahman22","ch":"jawahir","m":"gem","t":"يخرج منهما اللؤلؤ والمرجان","r":[55,22],"n":"من نعم الله في البحرين: «يخرج منهما اللؤلؤ والمرجان».","q":[{"w":"السعدي","bk":"saadi","s":55,"ay":22,"x":"المراد بالبحرين: البحر العذب والبحر المالح؛ فهما يلتقيان [كلاهما]، فيصبُّ العذب في البحر المالح ويختلطان ويمتزجان، ولكنَّ الله تعالى جعل بينهما برزخاً من الأرض، حتى لا يبغي أحدهما على الآخر، ويحصُلَ النفع بكلٍّ منهما؛ فالعذب منه يشربون وتشرب أشجارهم وزروعهم وحروثهم، والملح به يطيبُ الهواء ويتولَّد الحوت والسمك واللؤلؤ والمرجان …","en":"Al-Sa'di: What is meant by the two seas is the fresh sea and the salt sea; they meet, the fresh pouring into the salt and mixing and blending, but Allah placed between them a barrier of earth so that neither transgresses on the other and benefit is gained from each: from the fresh they drink and their trees, crops and tillage drink, and by the salt the air becomes pleasant and fish and pearl and coral are generated …"}],"h":[]},{"id":"rahman58","ch":"jawahir","m":"gem","t":"كأنهن الياقوت والمرجان","r":[55,58],"n":"شبّه الله نساء الجنة في صفائهن وجمالهن بالياقوت والمرجان.","q":[{"w":"السعدي","bk":"saadi","s":55,"ay":58,"x":"{فيهنَّ قاصراتُ الطرفِ}؛ أي: قد قصرنَ طرفهنَّ على أزواجهنَّ من حسنهم وجمالهم وكمال محبتهنَّ لهم، وقصرنَ أيضاً طرفَ أزواجهنَّ عليهنَّ من حسنهنَّ وجمالهنَّ ولَذَّةِ وصالهنَّ وشدَّة محبَّتهنَّ، {لم يطمثهنَّ إنسٌ قبلَهم ولا جانٌّ}؛ أي: لم ينلهنَّ أحدٌ قبلهم من الإنس والجنِّ، بل هنَّ أبكارٌ عربٌ متحبِّباتٌ إلى أزواجهنَّ؛ بحسن التبعُّل والتغنُّج والملاحة والدَّلال، ولهذا قال:{كأنهنَّ الياقوت والمرجان}، وذلك لصفائهنَّ وجمال منظرهنَّ وبهائهنَّ.","en":"Al-Sa'di: \"In them are maidens restraining their glances\", meaning they restrain their glances for their husbands out of their husbands' beauty and their own perfect love for them, and they also restrain their husbands' glances to themselves by their beauty, the pleasure of union with them and the intensity of their love; \"whom no man has touched before them, nor jinn\", meaning no one before them of men or jinn has reached them, but they are virgins, loving, endearing to their husbands by good companionship, coquetry, charm and daintiness; hence He said \"as if they were ruby and coral\", for their clarity, the beauty of their appearance and their radiance."}],"h":[]},{"id":"waqia23","ch":"jawahir","m":"gem","t":"كأمثال اللؤلؤ المكنون","r":[56,22,23],"n":"شبّه الله الحور العين باللؤلؤ المكنون المستور المصون.","q":[{"w":"السعدي","bk":"saadi","s":56,"ay":22,"x":"{كأمثال اللُّؤلؤ المكنونِ}؛ أي: كأنَّهن اللؤلؤ [الأبيض] الرطبُ الصافي البهيُّ المستور عن الأعين والريح والشمس، الذي يكون لونُه من أحسن الألوان، الذي لا عيب فيه بوجهٍ من الوجوه؛ فكذلك الحور العين، لا عيبَ فيهنَّ بوجهٍ، بل هنَّ كاملاتُ الأوصاف جميلاتُ النُّعوت؛ فكلُّ ما تأمَّلته منها؛ لم تجدْ فيه إلاَّ ما يسرُّ القلب ويروق الناظر.","en":"Al-Sa'di: \"Like pearls well guarded\", meaning as if they were white, fresh, clear, radiant pearl, hidden from eyes, wind and sun, whose colour is among the finest of colours, with no flaw in any respect; so are the wide-eyed maidens, no flaw in them in any respect, but perfect in attributes and beautiful in description; everything you contemplate of them, you find only what delights the heart and pleases the eye."}],"h":[]},{"id":"hijr19","ch":"ard","m":"earth","t":"وأنبتنا فيها من كل شيء موزون","r":[15,19],"n":"من نعم الله في الأرض: «وأنبتنا فيها من كل شيء موزون»، وفي تفسير السعدي أن مما يشمله ذلك المعادن.","q":[{"w":"السعدي","bk":"saadi","s":15,"ay":19,"x":"{وأنبَتۡنا فيها من كلِّ شيءٍ موزونٍ}؛ أي: نافع متقوَّم يضطرُّ إليه العباد والبلاد ما بين نخيل وأعناب وأصناف الأشجار وأنواع النبات والمعادن.","en":"Al-Sa'di: \"And We caused to grow in it everything weighed\", meaning beneficial and well measured, which servants and lands need, among palms, grapes, kinds of trees, kinds of plants and minerals."}],"h":[]},{"id":"zalzala2","ch":"ard","m":"earth","t":"وأخرجت الأرض أثقالها","r":[99,2],"n":"يوم القيامة تُخرج الأرض أثقالها، وفسّر السعدي الأثقال بما في بطنها من الأموات والكنوز.","q":[{"w":"السعدي","bk":"saadi","s":99,"ay":2,"x":"يخبر تعالى عمَّا يكون يوم القيامة، وأنَّ الأرض تتزلزل وترجف وترتجُّ حتى يسقطَ ما عليها من بناءٍ ومَعْلَمٍ ، فتندكُّ جبالها، وتسوَّى تلالُها، وتكون قاعاً صفصفاً لا عوج فيه ولا أمتا، {وأخرجت الأرضُ أثقالها}؛ أي: ما في بطنها من الأموات والكنوز …","en":"Al-Sa'di: Allah informs about what will be on the Day of Resurrection: the earth will shake, quake and tremble until what is on it of buildings and landmarks falls, its mountains crumble, its hills are levelled and it becomes a level plain with no crookedness or unevenness in it; \"and the earth brings out its burdens\", meaning what is in its belly of the dead and of treasures …"}],"h":[]},{"id":"qasas76","ch":"ard","m":"au","t":"كنوز قارون ومفاتحه","r":[28,76],"n":"آتى الله قارون من الكنوز ما إن مفاتحه لتنوء بالعصبة أولي القوة، ثم نصحه قومه ألا يفرح بدنياه؛ ولم تحدّد الآية نوع الكنز، وذكر السعدي أنها كنوز الأموال.","q":[{"w":"السعدي","bk":"saadi","s":28,"ay":76,"x":"يخبر تعالى عن حالة قارون وما فَعَلَ وفُعِلَ به ونُصِحَ ووُعِظَ، فقال:{إنَّ قارون كان من قوم موسى}؛ أي: من بني إسرائيل، الذين فَضَلوا العالمين وفاقوهم في زمانهم، وامتَنَّ الله عليهم بما امتنَّ به، فكانت حالُهم مناسبةً للاستقامة، ولكنَّ قارون هذا بغى على قومه، وطغى بما أوتِيَه من الأموال العظيمة المُطْغِيَة، {وآتَيۡناه من الكنوزِ}؛ أي: كنوز الأموال شيئاً كثيراً، {ما إنَّ مفاتِحَهُ لَتنوءُ بالعصبةِ أولي القوَّةِ}: والعُصبة من العشرة إلى التسعة إلى السبعة ونحو ذلك؛ أي: حتى إنَّ مفاتح خزائنِ أموالِهِ تُثْقِلُ الجماعةَ القويةَ عن حملها؛ هذه المفاتيح؛ فما ظنُّك بالخزائن؟! {إذ قال له قومُهُ}: ناصحين له محذِّرين له عن الطُّغيان: {لا تَفۡرَحۡ إن الله لا يحبُّ الفرِحينَ}؛ أي: لا تفرحْ بهذه الدُّنيا العظيمة، وتفتخرْ بها، وتلهيك عن الآخرة؛ فإنَّ الله لا يحبُّ الفرحين بها المكبِّين على محبَّتها.","en":"Al-Sa'di: Allah informs of the state of Qarun and what he did, what was done to him, and how he was advised and admonished: \"Indeed Qarun was of the people of Musa\", meaning of the Children of Israel, who excelled the worlds and surpassed them in their time, and Allah favoured them with what He favoured them; their state was suited to uprightness, but this Qarun transgressed against his people and tyrannised by the great, tyranny-inducing wealth he was given; \"and We gave him of the treasures\", meaning treasures of wealth, a great deal, \"whose keys would burden a company of strong men\": a company is from ten to nine to seven or so, meaning the keys of his treasuries of wealth weighed down the strong group from carrying them; so what do you think of the treasuries? \"When his people said to him\", advising him and warning him against tyranny: \"Do not exult; indeed Allah does not like the exultant\", meaning do not exult in this great world and boast of it so that it distracts you from the Hereafter; for Allah does not like those who exult in it and are absorbed in loving it."}],"h":[]},{"id":"fatir27","ch":"ard","m":"earth","t":"جدد بيض وحمر مختلف ألوانها","r":[35,27],"n":"من آيات الله في الجبال طرائق بيض وحمر مختلف ألوانها وغرابيب سود.","q":[{"w":"السعدي","bk":"saadi","s":35,"ay":27,"x":"ومن ذلك الجبالُ التي جعلها الله أوتاداً للأرض؛ تجدِها جبالاً مشتبكةً، بل جبلاً واحداً، وفيها ألوان متعددةٌ، فيها {جُدَدٌ بيضٌ}؛ أي: طرائق بيضٌ، وفيها طرائقُ صفرٌ وحمرٌ، وفيها {غرابيبُ سودٌ}؛ أي: شديدة السواد جدًّا.","en":"Al-Sa'di: And among that are the mountains which Allah made pegs for the earth; you find them interlocked mountains, indeed one mountain, with many colours in it: \"streaks of white\", meaning white tracts, and in them are tracts of yellow and red, and \"intensely black ones\", meaning extremely black."}],"h":[]},{"id":"baqara267","ch":"ard","m":"earth au ag","t":"ومما أخرجنا لكم من الأرض","r":[2,267],"n":"أمر الله بالإنفاق من طيبات ما كسب المؤمنون ومما أخرج لهم من الأرض؛ وبيّن القرطبي أن ما أُخرج يشمل النبات والمعادن والركاز.","q":[{"w":"القرطبي","bk":"qurtubi","s":2,"ay":267,"x":"الرَّابِعَةُ- قَوْلُهُ تَعَالَى: ﴿وَمِمَّا أَخْرَجْنا لَكُمْ مِنَ الْأَرْضِ﴾ يَعْنِي النَّبَاتَ وَالْمَعَادِنَ وَالرِّكَازَ، وَهَذِهِ أَبْوَابٌ ثَلَاثَةٌ تَضَمَّنَتْهَا هَذِهِ الْآيَةُ.","en":"Al-Qurtubi: The fourth: His saying \"and from what We brought out for you from the earth\" means plants, minerals and buried treasure, and these are three chapters this verse contains."},{"w":"القرطبي","bk":"qurtubi","s":2,"ay":267,"x":"قَالَ عُلَمَاؤُنَا: لَمَّا قَالَ ﷺ: \"وَفِي الرِّكَازِ الْخُمُسُ\" دَلَّ عَلَى أَنَّ الْحُكْمَ فِي الْمَعَادِنِ غَيْرُ الْحُكْمِ فِي الرِّكَازِ، لِأَنَّهُ ﷺ قَدْ فَصَلَ بَيْنَ الْمَعَادِنِ وَالرِّكَازِ بِالْوَاوِ الْفَاصِلَةِ، وَلَوْ كَانَ الْحُكْمُ فِيهِمَا سَوَاءٌ لَقَالَ وَالْمَعْدِنُ جُبَارٌ وَفِيهِ الْخُمُسُ، فَلَمَّا قَالَ \"وَفِي الرِّكَازِ الْخُمُسُ\" عُلِمَ أَنَّ حُكْمَ الرِّكَازِ غَيْرُ حُكْمِ الْمَعْدِنِ فِيمَا يُؤْخَذُ مِنْهُ، وَاللَّهُ أَعْلَمُ. وَالرِّكَازُ أَصْلُهُ فِي اللُّغَةِ مَا ارْتَكَزَ بِالْأَرْضِ مِنَ الذَّهَبِ وَالْفِضَّةِ وَالْجَوَاهِرِ، وَهُوَ عِنْدَ سَائِرِ الْفُقَهَاءِ كَذَلِكَ، لِأَنَّهُمْ يَقُولُونَ فِي النَّدْرَةِ الَّتِي تُوجَدُ فِي الْمَعْدِنِ مُرْتَكِزَةً بِالْأَرْضِ لَا تُنَالُ بِعَمَلٍ وَلَا بِسَعْيٍ وَلَا نَصَبٍ، فِيهَا الْخُمُسُ، لِأَنَّهَا رِكَازٌ.","en":"Al-Qurtubi: Our scholars said: when the Prophet, peace be upon him, said \"and in buried treasure is the fifth\", it indicated that the ruling on minerals differs from the ruling on buried treasure, because he separated minerals and buried treasure with the conjunction; had the ruling been the same, he would have said \"the mine is without liability and in it is the fifth\"; so when he said \"and in buried treasure is the fifth\", it was known that the ruling on buried treasure differs from the ruling on the mine in what is taken from it, and Allah knows best. And \"rikaz\" originally in the language is what is embedded in the earth of gold, silver and gems, and it is so among all the jurists, because they say about the nugget found in the mine embedded in the earth, not obtained by work, effort or toil, that the fifth is due on it, because it is rikaz."}],"h":[{"b":"صحيح البخاري","bk":"bukhari","n":"1499","x":"الْعَجْمَاءُ جُبَارٌ، وَالْبِئْرُ جُبَارٌ، وَالْمَعْدِنُ جُبَارٌ، وَفِي الرِّكَازِ الْخُمُسُ","en":"The Prophet, peace be upon him, said: \"The beast's injury is without liability, the well is without liability, the mine is without liability, and in buried treasure is the fifth.\""}]}],"ay":{"273":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ","306":"زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلۡبَنِينَ وَٱلۡقَنَٰطِيرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَيۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَٰمِ وَٱلۡحَرۡثِۗ ذَٰلِكَ مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ","367":"۞ وَمِنۡ أَهۡلِ ٱلۡكِتَٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارٖ يُؤَدِّهِۦٓ إِلَيۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِينَارٖ لَّا يُؤَدِّهِۦٓ إِلَيۡكَ إِلَّا مَا دُمۡتَ عَلَيۡهِ قَآئِمٗاۗ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لَيۡسَ عَلَيۡنَا فِي ٱلۡأُمِّيِّـۧنَ سَبِيلٞ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ يَعۡلَمُونَ","383":"إِنَّ ٱلَّذِينَ كَفَرُواْ وَمَاتُواْ وَهُمۡ كُفَّارٞ فَلَن يُقۡبَلَ مِنۡ أَحَدِهِم مِّلۡءُ ٱلۡأَرۡضِ ذَهَبٗا وَلَوِ ٱفۡتَدَىٰ بِهِۦٓۗ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ وَمَا لَهُم مِّن نَّٰصِرِينَ","1268":"۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ كَثِيرٗا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَيَأۡكُلُونَ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۗ وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٖ","1269":"يَوۡمَ يُحۡمَىٰ عَلَيۡهَا فِي نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ هَٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُواْ مَا كُنتُمۡ تَكۡنِزُونَ","1615":"وَشَرَوۡهُ بِثَمَنِۭ بَخۡسٖ دَرَٰهِمَ مَعۡدُودَةٖ وَكَانُواْ فِيهِ مِنَ ٱلزَّٰهِدِينَ","1723":"أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَالَتۡ أَوۡدِيَةُۢ بِقَدَرِهَا فَٱحۡتَمَلَ ٱلسَّيۡلُ زَبَدٗا رَّابِيٗاۖ وَمِمَّا يُوقِدُونَ عَلَيۡهِ فِي ٱلنَّارِ ٱبۡتِغَآءَ حِلۡيَةٍ أَوۡ مَتَٰعٖ زَبَدٞ مِّثۡلُهُۥۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡحَقَّ وَٱلۡبَٰطِلَۚ فَأَمَّا ٱلزَّبَدُ فَيَذۡهَبُ جُفَآءٗۖ وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمۡكُثُ فِي ٱلۡأَرۡضِۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ","1820":"وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ شَيۡءٖ مَّوۡزُونٖ","2078":"۞ قُلۡ كُونُواْ حِجَارَةً أَوۡ حَدِيدًا","2079":"أَوۡ خَلۡقٗا مِّمَّا يَكۡبُرُ فِي صُدُورِكُمۡۚ فَسَيَقُولُونَ مَن يُعِيدُنَاۖ قُلِ ٱلَّذِي فَطَرَكُمۡ أَوَّلَ مَرَّةٖۚ فَسَيُنۡغِضُونَ إِلَيۡكَ رُءُوسَهُمۡ وَيَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰٓ أَن يَكُونَ قَرِيبٗا","2158":"وَكَذَٰلِكَ بَعَثۡنَٰهُمۡ لِيَتَسَآءَلُواْ بَيۡنَهُمۡۚ قَالَ قَآئِلٞ مِّنۡهُمۡ كَمۡ لَبِثۡتُمۡۖ قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۚ قَالُواْ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ فَٱبۡعَثُوٓاْ أَحَدَكُم بِوَرِقِكُمۡ هَٰذِهِۦٓ إِلَى ٱلۡمَدِينَةِ فَلۡيَنظُرۡ أَيُّهَآ أَزۡكَىٰ طَعَامٗا فَلۡيَأۡتِكُم بِرِزۡقٖ مِّنۡهُ وَلۡيَتَلَطَّفۡ وَلَا يُشۡعِرَنَّ بِكُمۡ أَحَدًا","2168":"وَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَآءَ فَلۡيُؤۡمِن وَمَن شَآءَ فَلۡيَكۡفُرۡۚ إِنَّآ أَعۡتَدۡنَا لِلظَّٰلِمِينَ نَارًا أَحَاطَ بِهِمۡ سُرَادِقُهَاۚ وَإِن يَسۡتَغِيثُواْ يُغَاثُواْ بِمَآءٖ كَٱلۡمُهۡلِ يَشۡوِي ٱلۡوُجُوهَۚ بِئۡسَ ٱلشَّرَابُ وَسَآءَتۡ مُرۡتَفَقًا","2170":"أُوْلَٰٓئِكَ لَهُمۡ جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَيَلۡبَسُونَ ثِيَابًا خُضۡرٗا مِّن سُندُسٖ وَإِسۡتَبۡرَقٖ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۚ نِعۡمَ ٱلثَّوَابُ وَحَسُنَتۡ مُرۡتَفَقٗا","2235":"ءَاتُونِي زُبَرَ ٱلۡحَدِيدِۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيۡنَ ٱلصَّدَفَيۡنِ قَالَ ٱنفُخُواْۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارٗا قَالَ ءَاتُونِيٓ أُفۡرِغۡ عَلَيۡهِ قِطۡرٗا","2236":"فَمَا ٱسۡطَٰعُوٓاْ أَن يَظۡهَرُوهُ وَمَا ٱسۡتَطَٰعُواْ لَهُۥ نَقۡبٗا","2562":"وَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسٖ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَٰكِرُونَ","2615":"وَلَهُم مَّقَٰمِعُ مِنۡ حَدِيدٖ","3327":"۞ إِنَّ قَٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَيۡهِمۡۖ وَءَاتَيۡنَٰهُ مِنَ ٱلۡكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ بِٱلۡعُصۡبَةِ أُوْلِي ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ","3615":"۞ وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلٗاۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ","3616":"أَنِ ٱعۡمَلۡ سَٰبِغَٰتٖ وَقَدِّرۡ فِي ٱلسَّرۡدِۖ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ بَصِيرٞ","3617":"وَلِسُلَيۡمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهۡرٞ وَرَوَاحُهَا شَهۡرٞۖ وَأَسَلۡنَا لَهُۥ عَيۡنَ ٱلۡقِطۡرِۖ وَمِنَ ٱلۡجِنِّ مَن يَعۡمَلُ بَيۡنَ يَدَيۡهِ بِإِذۡنِ رَبِّهِۦۖ وَمَن يَزِغۡ مِنۡهُمۡ عَنۡ أَمۡرِنَا نُذِقۡهُ مِنۡ عَذَابِ ٱلسَّعِيرِ","3686":"أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَخۡرَجۡنَا بِهِۦ ثَمَرَٰتٖ مُّخۡتَلِفًا أَلۡوَٰنُهَاۚ وَمِنَ ٱلۡجِبَالِ جُدَدُۢ بِيضٞ وَحُمۡرٞ مُّخۡتَلِفٌ أَلۡوَٰنُهَا وَغَرَابِيبُ سُودٞ","3692":"جَنَّٰتُ عَدۡنٖ يَدۡخُلُونَهَا يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَلُؤۡلُؤٗاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرٞ","4357":"وَلَوۡلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ لَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ وَمَعَارِجَ عَلَيۡهَا يَظۡهَرُونَ","4358":"وَلِبُيُوتِهِمۡ أَبۡوَٰبٗا وَسُرُرًا عَلَيۡهَا يَتَّكِـُٔونَ","4359":"وَزُخۡرُفٗاۚ وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَٱلۡأٓخِرَةُ عِندَ رَبِّكَ لِلۡمُتَّقِينَ","4377":"فَلَوۡلَآ أُلۡقِيَ عَلَيۡهِ أَسۡوِرَةٞ مِّن ذَهَبٍ أَوۡ جَآءَ مَعَهُ ٱلۡمَلَٰٓئِكَةُ مُقۡتَرِنِينَ","4395":"يُطَافُ عَلَيۡهِم بِصِحَافٖ مِّن ذَهَبٖ وَأَكۡوَابٖۖ وَفِيهَا مَا تَشۡتَهِيهِ ٱلۡأَنفُسُ وَتَلَذُّ ٱلۡأَعۡيُنُۖ وَأَنتُمۡ فِيهَا خَٰلِدُونَ","4456":"إِنَّ شَجَرَتَ ٱلزَّقُّومِ","4457":"طَعَامُ ٱلۡأَثِيمِ","4458":"كَٱلۡمُهۡلِ يَغۡلِي فِي ٱلۡبُطُونِ","4459":"كَغَلۡيِ ٱلۡحَمِيمِ","4651":"لَّقَدۡ كُنتَ فِي غَفۡلَةٖ مِّنۡ هَٰذَا فَكَشَفۡنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلۡيَوۡمَ حَدِيدٞ","4922":"يَخۡرُجُ مِنۡهُمَا ٱللُّؤۡلُؤُ وَٱلۡمَرۡجَانُ","4935":"يُرۡسَلُ عَلَيۡكُمَا شُوَاظٞ مِّن نَّارٖ وَنُحَاسٞ فَلَا تَنتَصِرَانِ","4936":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","4958":"كَأَنَّهُنَّ ٱلۡيَاقُوتُ وَٱلۡمَرۡجَانُ","5000":"وَحُورٌ عِينٞ","5001":"كَأَمۡثَٰلِ ٱللُّؤۡلُوِٕ ٱلۡمَكۡنُونِ","5099":"لَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَيِّنَٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسٞ شَدِيدٞ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعۡلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلۡغَيۡبِۚ إِنَّ ٱللَّهَ قَوِيٌّ عَزِيزٞ","5382":"يَوۡمَ تَكُونُ ٱلسَّمَآءُ كَٱلۡمُهۡلِ","5383":"وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ","5605":"وَيُطَافُ عَلَيۡهِم بِـَٔانِيَةٖ مِّن فِضَّةٖ وَأَكۡوَابٖ كَانَتۡ قَوَارِيرَا۠","5606":"قَوَارِيرَاْ مِن فِضَّةٖ قَدَّرُوهَا تَقۡدِيرٗا","5611":"عَٰلِيَهُمۡ ثِيَابُ سُندُسٍ خُضۡرٞ وَإِسۡتَبۡرَقٞۖ وَحُلُّوٓاْ أَسَاوِرَ مِن فِضَّةٖ وَسَقَىٰهُمۡ رَبُّهُمۡ شَرَابٗا طَهُورًا","6139":"وَأَخۡرَجَتِ ٱلۡأَرۡضُ أَثۡقَالَهَا"},"nay":47,"nq":44,"nh":6};
